"""review-loop の通し確認に使う、試験用の小さなモジュール。"""


def clamp(value, low, high):
    """value を low 以上 high 以下に収めて返す。low が high より大きいときは ValueError を送出する。"""
    if low > high:
        raise ValueError(f"low ({low}) が high ({high}) より大きい")
    return max(low, min(value, high))
EOF
